const fs = require('node:fs');
const path = require('node:path');
const parts = ['jszip/dist/jszip.min.js', 'epubjs/dist/epub.min.js'];
const code = parts.map((name) => fs.readFileSync(require.resolve(name), 'utf8').replace(/\/\/# sourceMappingURL=.*$/gm, '')).join('\n');
fs.writeFileSync(path.join(__dirname, '../src/reader/vendor/engine.ts'), '// Generated by scripts/bundle-reader.cjs from pinned npm dependencies.\nexport const engine = ' + JSON.stringify(code) + ';\n');
fs.copyFileSync(require.resolve('epubjs/license'), path.join(__dirname, '../src/reader/vendor/EPUBJS-LICENSE'));
fs.copyFileSync(require.resolve('jszip/LICENSE.markdown'), path.join(__dirname, '../src/reader/vendor/JSZIP-LICENSE'));
const notices = [
  ['epub.js', 'epubjs/license'],
  ['JSZip', 'jszip/LICENSE.markdown'],
  ['Instrument Sans', '@expo-google-fonts/instrument-sans/LICENSE_FONT'],
].map(([name, file]) => ({ name, text: fs.readFileSync(require.resolve(file), 'utf8') }));
fs.writeFileSync(path.join(__dirname, '../src/reader/vendor/notices.ts'), '// Generated by scripts/bundle-reader.cjs.\nexport const notices = ' + JSON.stringify(notices) + ';\n');
